# The McGee graph has 24 vertices, 3-regular, girth 7. Maybe add 2 extra vertices with degree 3-4.
# Or try a (3,7)-cage has 24 vertices. So 26 vertices exists? Moore bound for 3-reg girth 7: need >= 24.
# Let's try SAT/CP approach using backtracking with more structure.
# Or use local search: build, then if incomplete, do edge swaps.

import random
from collections import deque

def bfs_dist(adj, s, limit):
    dist = {s: 0}
    q = deque([s])
    while q:
        u = q.popleft()
        if dist[u] >= limit: continue
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u]+1
                q.append(v)
    return dist

def shortest_cycle_through_edge(adj, u, v):
    # distance from u to v without using edge uv
    adj[u].discard(v); adj[v].discard(u)
    d = bfs_dist(adj, u, 100)
    adj[u].add(v); adj[v].add(u)
    return d.get(v, float('inf')) + 1

def try_build(n=26, girth=7, dmin=3, dmax=4, seed=0, max_time=5000):
    random.seed(seed)
    adj = {i:set() for i in range(n)}

    def can_add(u,v):
        if v in adj[u] or u==v: return False
        if len(adj[u])>=dmax or len(adj[v])>=dmax: return False
        d = bfs_dist(adj, u, girth-1)
        return not (v in d and d[v] < girth-1)

    # phase 1: greedy
    for it in range(max_time):
        low = [i for i in range(n) if len(adj[i])<dmin]
        if not low:
            break
        u = random.choice(low)
        cands = [v for v in range(n) if can_add(u,v)]
        if cands:
            v = random.choice(cands)
            adj[u].add(v); adj[v].add(u)
        else:
            # do an edge swap: remove a random edge and try again
            # pick random edge not incident to u that has high-degree endpoints
            all_edges = [(a,b) for a in range(n) for b in adj[a] if a<b]
            if not all_edges: continue
            random.shuffle(all_edges)
            for a,b in all_edges[:20]:
                if a==u or b==u: continue
                adj[a].discard(b); adj[b].discard(a)
                break

    degs = [len(adj[i]) for i in range(n)]
    if all(dmin<=d<=dmax for d in degs):
        edges = [(a,b) for a in range(n) for b in adj[a] if a<b]
        # verify girth
        return edges, adj
    return None

best = None
for seed in range(2000):
    r = try_build(seed=seed)
    if r:
        best = r
        print("found seed", seed)
        break

if best:
    edges, adj = best
    # verify girth
    def girth_check(adj, n):
        g = float('inf')
        for s in range(n):
            dist = {s:0}
            parent = {s:-1}
            q = deque([s])
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if v not in dist:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        q.append(v)
                    elif parent[u]!=v:
                        g = min(g, dist[u]+dist[v]+1)
        return g
    print("girth:", girth_check(adj, 26))
    print("degs:", [len(adj[i]) for i in range(26)])
    print("edges:", edges)
else:
    print("none found")
